# Incremental task history: 30 rows per request. Reset on project change.
@app.callback(
    Output("task-history-page", "data"),
    Input("task-history-more", "n_clicks"),
    Input("overview-project-filter", "value"),
    State("task-history-page", "data"),
    prevent_initial_call=True
)
def page_task_history(clicks, selected_project, current):
    from dash import ctx
    if ctx.triggered_id == "overview-project-filter":
        return 30
    if ctx.triggered_id == "task-history-more" and clicks:
        return max(30, int(current or 30)) + 30
    return no_update
